```
Create a PHP wrapper class for the MailMasterPlus API to integrate with SalesAutopilot. The wrapper should include methods for [ACTIONS] such as sending emails, managing lists, and tracking campaigns. Use [COMPANY]'s branding guidelines and ensure the code follows [INDUSTRY] best practices for security and performance. Provide error handling and logging capabilities.
```
Copy

```
```php
<?php

class MailMasterPlusWrapper {
    private $apiKey;
    private $baseUrl = 'https://api.mailmasterplus.com/v1/';

    public function __construct($apiKey) {
        $this->apiKey = $apiKey;
    }

    public function sendEmail($to, $subject, $body, $from = null) {
        $endpoint = 'emails/send';
        $data = [
            'to' => $to,
            'subject' => $subject,
            'body' => $body,
            'from' => $from ?: 'noreply@mailmasterplus.com'
        ];

        return $this->makeRequest('POST', $endpoint, $data);
    }

    private function makeRequest($method, $endpoint, $data = []) {
        $headers = [
            'Authorization: Bearer ' . $this->apiKey,
            'Content-Type: application/json'
        ];

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $this->baseUrl . $endpoint);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        if ($method === 'POST') {
            curl_setopt($ch, CURLOPT_POST, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
        }

        $response = curl_exec($ch);
        curl_close($ch);

        return json_decode($response, true);
    }
}

// Example usage:
$wrapper = new MailMasterPlusWrapper('your_api_key_here');
$wrapper->sendEmail(
    'customer@example.com',
    'Welcome to Our Newsletter',
    'Thank you for subscribing to our newsletter. Here is your first email.'
);
```
